--初始化数据
function UIFishPoolFishAltasDialog:InitData()
    self._togParData = {
        {
            name = localize("渔场图鉴"),
            bgPath = "Arts/Icons/HomeLabel/tab_ico_fishingground.png",
            func = function()
            end,
            redPointFun = function()
                return FishingUtils.IsHaveCanDrawAtlasRewardPlace()
            end
        }
    }

    if checkNumber(self._curFishPlaceId) == 0 then
    else
        table.insert(self._togParData, {
            name = localize("收藏品"),
            bgPath = "Arts/Icons/HomeLabel/tab_ico_collection.png",
            func = function()
            end,
            redPointFun = function()
                return FishingUtils.IsHaveNoDrawReard()
            end
        })
    end

    local t = {}
    local allPlace = FishingUtils.GetAllFishPlace()
    local _t = {}
    for k, v in pairs(allPlace) do
        local data = {
            name = v.name,
            id = v.id,
            func = function(data)
                self:FillAtilasNode(data.id)
            end,
            redPointFun = function()
                return FishingUtils.IsHaveCanDrawAtlasReward(v.id)
            end
        }
        table.insert(_t, data)
    end
    table.insert(t, _t)

    if checkNumber(self._curFishPlaceId) == 0 then
    else
        local allEggGroupVo = FishingUtils.GetAllEggGroupVo()
        _t = {}
        for k, v in pairs(allEggGroupVo) do
            local data = {
                name = v.name,
                id = v.id,
                func = function(data)
                    self:FillEggsNode(data.id)
                end,
                redPointFun = function()
                    return FishingUtils.IsCanDrawReard(v.id)
                end
            }
            table.insert(_t, data)
        end
        table.insert(t, _t)
    end


    self._togChildData = t
end

function UIFishPoolFishAltasDialog:FillSelf()
    if checkNumber(self._curFishPlaceId) == 0 then
        local scr = CfUtils.GetLuaScr(self.CommonTabToggleLeftExpand, CommonTabToggleLeftExpand)
        if scr then
            scr:Refresh(self._togParData, self._togChildData, 1, self:GetPlaceInd())
        end
    else
        self:FillAtilasNode(self._curFishPlaceId)
    end
end

function UIFishPoolFishAltasDialog:FillAtilasNode(placeId)
    self._curType = Type.Atlas
    self._curFishPlaceId = placeId
    KTool.SetActive(self.CollectProgress, false)
    KTool.SetActive(self.CollectionsGoodsDetails, false)
    KTool.SetActive(self.FishAltasRecordPanel, false)
    KTool.SetActive(self.Empty, true)
    KTool.SetActive(self.FishLevelReward, true)

    local t = FishingUtils.GetAllFishVoByPlaceId(placeId)
    if not t then
        return
    end
    self._listData = t
    self:RefreshList()
    self:FillBoxInfo(placeId)
end

function UIFishPoolFishAltasDialog:FillEggsNode(groupId)
    self._curType = Type.Eggs
    KTool.SetActive(self.CollectProgress, true)
    KTool.SetActive(self.CollectionsGoodsDetails, false)
    KTool.SetActive(self.FishAltasRecordPanel, false)
    KTool.SetActive(self.Empty, true)
    KTool.SetActive(self.FishLevelReward, false)

    self._listData = {}
    local vo = FishingUtils.GetFishEasterEggsGroupVo(groupId)
    if vo then
        self._listData = CfUtils.Split(vo.item)
    end
    self:RefreshList()
    self:FillBoxInfo(groupId)
    self._curEggGroupId = groupId
end

function UIFishPoolFishAltasDialog:FillBoxInfo(id)
    if self._curType == Type.Eggs then
        self:FillEggsBoxInfo(id)
    else
        self:FillAtlasBoxInfo(id)
    end
end

function UIFishPoolFishAltasDialog:FillAtlasBoxInfo(placeId)
    local t = FishingUtils.GetAllAtlasRewardId(self._curFishPlaceId)
    local count = 0
    for i = 1, 4 do
        local go = self["Group"..i]
        local data = FishingUtils.GetFishingAtlasRewardVo(t[i])
        self:FillAtlasBox(go, data, i)

        local isDraw = FishingUtils.IsDrawAtlasReward(data.id)
        if isDraw then
            count = count + 1
        end
    end
    --self.Slider1.value = count / table.count(t)
end

function UIFishPoolFishAltasDialog:FillAtlasBox(go, data, ind)
    if not go or not data then
        return
    end
    print(table.dump(data))
    local _, num = FishingUtils.GetAtlasGetNum(self._curFishPlaceId)
    local num1 = FishingUtils.GetFishEnoughNum(data.id)
    CfUtils.FillText(go.transform:Find("TextNumber"), num1.."/"..num)
    local slider = go.transform:Find('Slider').transform:GetComponent(typeof(Image))
    slider.fillAmount = num1 / num

    local isDraw = FishingUtils.IsDrawAtlasReward(data.id)
    local isUnlock = FishingUtils.IsUnlockAtlasId(data.id)
    local isCanDraw = (isUnlock and not isDraw)

    local redGo = GameUtils.GetRedPointGo(go)
    CfUtils.SetActive(redGo, isCanDraw)

    CfUtils.SetUISwitchText(go.transform:Find("TextNumber"), isUnlock and 2 or 1)
    local starGo = self.FishLevelReward.transform:Find("StarNode/ImgStar"..ind)
    CfUtils.SetUISwitchImage(starGo, isUnlock and 2 or 1)

    CfUtils.SetActive(go.transform:Find("RewardGroup/StatusIsReceive"), isDraw)

    local statusNormalGo = go.transform:Find("RewardGroup/StatusNormal")
    CfUtils.PlayAnimator(statusNormalGo, isCanDraw and "CanTake" or "Idle")

    CfUtils.SetUISwitchImage(go.transform:Find("FishGrade/ImgIcon"), checkNumber(data.grade) == 6 and 2 or 1)
    CfUtils.SetUISwitchImage(go.transform:Find("FishGrade/ImgGrade"), data.grade)

    local t = {}
    local t1 = CfUtils.Split(data.reward)
    local t2 = CfUtils.Split(data.rewardNum)
    for i = 1, table.count(t1) do
        table.insert(t, {
            goodsId = t1[i],
            num = t2[i]
        })
    end
    SetButtonAction(go.transform:Find("RewardGroup"), function()
        if not isUnlock then
            GameUtils.ShowCommonTipsBoardRewardPreview(go.gameObject, t, localize('奖励预览:'), false)
            --GameUtils.Toast(localize("该奖励未领取"))
            return
        elseif isDraw then
            GameUtils.Toast(localize("该奖励已领取"))
            return
        end
        self._co = cs_coroutine.start(function()
            CfUtils.PlayAnimator(statusNormalGo, "Open")
            coroutine.yield(WaitForSeconds(0.5))
            fishingComponent:DrawAtlasRewards(data.id, self._curFishPlaceId, function(rewards)
                self:FillBoxInfo(self._curFishPlaceId)
                CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
                --self:RefreshRedPoint()
        
                local scr = CfUtils.GetLuaScr(self.CommonTabToggleLeftExpand, CommonTabToggleLeftExpand)
                if scr then
                    scr:RedPointRefresh()
                end
            end)
        end)
    end)
end

--宝箱详情
function UIFishPoolFishAltasDialog:FillEggsBoxInfo(groupId)
    local groupVo = FishingUtils.GetFishEasterEggsGroupVo(groupId)
    if not groupVo then
        return
    end

    local curNum, allNum = FishingUtils.GetEasterEggsGetNum(groupVo.id)

    CfUtils.FillText(self.TextNumber, "<color=#f93a94>"..curNum.."</color>/"..allNum)
    self.Slider.value = curNum/allNum


    local isGet = FishingUtils.IsDrawEasterEggsReward(groupVo.id)
    KTool.SetActive(self.ImgHasReceived, isGet)

    local isMarkGray = true
    if curNum >= allNum then
        if not isGet then
            isMarkGray = false
            KTool.SetActive(self.StasusCanReceive, true)
        else
            KTool.SetActive(self.StasusCanReceive, false)
        end
    else
        KTool.SetActive(self.StasusCanReceive, false)
    end

    self.BoxIconNormal.transform:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(isMarkGray)
end

--领取奖励
function UIFishPoolFishAltasDialog:OnBtnDrawReward()
    if self._curType == Type.Eggs then
        self:DrawEggsReward()
    else
        self:DrawAtlasReward()
    end
end

function UIFishPoolFishAltasDialog:DrawAtlasReward()
    local vo = FishingUtils.GetFishingAtlasRewardVo(self._curFishPlaceId)
    if not vo then
        return
    end

    local isGet = FishingUtils.IsDrawAtlasReward(self._curFishPlaceId)
    if isGet then
        GameUtils.Toast(localize("该奖励已领取"))
        return
    end

    local curNum, allNum = FishingUtils.GetAtlasGetNum(self._curFishPlaceId)
    if curNum < allNum then
        local t = {}
        local t1 = CfUtils.Split(vo.reward)
        local t2 = CfUtils.Split(vo.rewardNum)
        for k, v in pairs(t1) do
            table.insert(t, {
                goodsId = t1[k],
                num = t2[k]
            })
        end

        GameUtils.ShowCommonTipsBoardRewardPreview(self.BtnIconStatus.gameObject, t, localize('奖励预览:'), false)
        return
    end

    fishingComponent:DrawAtlasRewards(self._curFishPlaceId, function(rewards)
        self:FillBoxInfo(self._curFishPlaceId)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        --self:RefreshRedPoint()

        local scr = CfUtils.GetLuaScr(self.CommonTabToggleLeftExpand, CommonTabToggleLeftExpand)
        if scr then
            scr:RedPointRefresh()
        end
    end)
end

function UIFishPoolFishAltasDialog:DrawEggsReward()
    local groupVo = FishingUtils.GetFishEasterEggsGroupVo(self._curEggGroupId)
    local isGet = FishingUtils.IsDrawEasterEggsReward(groupVo.id)
    if isGet then
        GameUtils.Toast(localize("该奖励已领取"))
        return
    end
    local curNum, allNum = FishingUtils.GetEasterEggsGetNum(groupVo.id)
    if curNum < allNum then
        local t = {}
        local t1 = CfUtils.Split(groupVo.reward)
        local t2 = CfUtils.Split(groupVo.rewardNum)
        for k, v in pairs(t1) do
            table.insert(t, {
                goodsId = t1[k],
                num = t2[k]
            })
        end

        GameUtils.ShowCommonTipsBoardRewardPreview(self.BtnIconStatus.gameObject, t, localize('奖励预览:'), false)
        return
    end
    fishingComponent:DrawEasterEggsGroupRewards(self._curEggGroupId, function(rewards)
        self:FillBoxInfo(self._curEggGroupId)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        --self:RefreshRedPoint()

        local scr = CfUtils.GetLuaScr(self.CommonTabToggleLeftExpand, CommonTabToggleLeftExpand)
        if scr then
            scr:RedPointRefresh()
        end
    end)
end

function UIFishPoolFishAltasDialog:RefreshList()
    self._curSelectItmeInd = 0
    --[[
    type = checkNumber(type)
    self._curTypeData = self._allFishVo[type]

    local num = 0
    for k, v in pairs(self._curTypeData) do
        if FishingUtils.IsCollectionGetFishById(v.id) then
            num = num + 1
        end
    end
    ]]
    --CfUtils.FillText(self.TextNumberFish, num.."/"..table.count(self._curTypeData))

    if self._isInitList then
        self.LoopList:SetListItemCount(table.count(self._listData))
    else
        self.LoopList:InitListView(0, Bind(self, self.OnRefreshIndex))
        self.LoopList:SetListItemCount(table.count(self._listData))

        self._isInitList = true
    end
end

function UIFishPoolFishAltasDialog:OnGetListItemByIndex(go)
    if isNull(go) then
        return
    end
end

function UIFishPoolFishAltasDialog:OnRefreshIndex(go, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = go
    local vo = self._listData[index + 1]
    local scr = CfUtils.GetLuaScr(cell, UIFishPoolFishAltasItemNode)
    if scr then
        scr:Refresh(vo, function()
            self:ChooseGoods(index + 1)
        end, self._curType)

        if (index + 1) == self._curSelectItmeInd then
            scr:RefreshSelectActive(true)
            if self._curType == Type.Atlas then
                self:FillAtlasInfo()
            else
                self:FillEggsInfo()
            end
        end
    end
    return cell
end

--选择物品
function UIFishPoolFishAltasDialog:ChooseGoods(ind)
    ind = checkNumber(ind)
    local go
    local lastSelectInd = self._curSelectItmeInd
    if checkNumber(lastSelectInd) > 0 then
        go = self.LoopList:GetShownItemByItemIndex(lastSelectInd - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIFishPoolFishAltasItemNode)
            if lastScr then
                lastScr:RefreshSelectActive(false)
            end
        end
    end

    self._curSelectItmeInd = ind

    local curSelectInd = self._curSelectItmeInd
    if checkNumber(curSelectInd) > 0 then
        go = self.LoopList:GetShownItemByItemIndex(curSelectInd - 1)
        if go then
            local curScr = CfUtils.GetLuaScr(go, UIFishPoolFishAltasItemNode)
            if curScr then
                curScr:RefreshSelectActive(true)
            end
        end
    end

    if self._curType == Type.Atlas then
        self:FillAtlasInfo()
    else
        print(self._listData[curSelectInd])
        self:FillEggsInfo()
    end
end

--彩蛋
function UIFishPoolFishAltasDialog:FillEggsInfo()
    KTool.SetActive(self.CollectionsGoodsDetails, true)
    KTool.SetActive(self.Empty, false)
    local id = self._listData[self._curSelectItmeInd]

    local isUnlock = FishingUtils.IsUnlockEasterEggsId(id)
    KTool.SetActive(self.StatusGet, isUnlock)
    KTool.SetActive(self.StatusNotGet, not isUnlock)

    local vo = FishingUtils.GetFishEasterEggsConditionVo(id)
    if vo then 
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
        if goodsVo then
            CfUtils.FillText(self.TextTitle, goodsVo.name)
            CfUtils.SetUISwitchImage(self.ImgRare2, checkNumber(goodsVo.quality))
            CfUtils.SetUISwitchImage(self.ImgRare1, checkNumber(goodsVo.quality))
            
            CfUtils.FillImage(self.ImgIconNormal, goodsVo.photoPath)
            CfUtils.FillImage(self.ImgRareBg, GoodsUtils.GetFishBgByQualityType(goodsVo.quality, true))
        end

        if not isUnlock then
            CfUtils.FillText(self.TextDescribe, vo.desc)
        else
            CfUtils.FillText(self.TextDescribe, goodsVo.desc)
        end
    end
end

--刷新信息
function UIFishPoolFishAltasDialog:FillAtlasInfo()
    KTool.SetActive(self.FishAltasRecordPanel, true)
    KTool.SetActive(self.Empty, false)
    local data = self._listData[self._curSelectItmeInd]
    local scr = CfUtils.GetLuaScr(self.FishRecordPanel, UIFishPoolFishAltasInfoNode)
    if scr then
        scr:Refresh(data)
    end
end

function UIFishPoolFishAltasDialog:GetPlaceInd()
    if checkNumber(self._curFishPlaceId) <= 0 then
        return 1
    end
    for k, v in pairs(self._togChildData[1]) do
        if checkNumber(v.id) == checkNumber(self._curFishPlaceId) then
            return k
        end
    end
    return 1
end

function UIFishPoolFishAltasDialog:OnCaptureAction()
    local effectBg = KTool.GetOrAddComponent(self.controller.gameObject, typeof(CS.UGUI.Effects.UIEffectCapturedImage))
    if effectBg then
        effectBg:Capture()
    end
end

function UIFishPoolFishAltasDialog:OnHide()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        FishingUtils.RefreshAtlasRedPointData()
        cs_coroutine.yield_return(self:OnCaptureAction())
    end))
    return coWait
end

function UIFishPoolFishAltasDialog:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        fishingComponent:FishingCollectionReq(function()
            self:FillSelf()
        end)
    end))
    return coWait
end

function UIFishPoolFishAltasDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if argument then
            self._curFishPlaceId = checkNumber(argument.fishPlaceId)
        end
        self:InitData()

    end))
    return coWait
end

function UIFishPoolFishAltasDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local num = 0
        if FishingUtils.IsHaveNoDrawReard() or FishingUtils.IsHaveCanDrawAtlasRewardPlace() then
            num = 1 
        end
        --GameUtils.SetRedPointNum(Constants.RedPointConst.PhoneFishCollection, num)

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFishPoolFishAltasDialog
